  FT["PH-H8696"] = {"id":"PH-H8696","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10243_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"The Judiciary Reorganization Act of 1980","orig":"An Act Cheating Three (3) Additional Branches of the Regional Trial Court to Be Stationed At the City of Davao, Amending for the Purpose Section 14, Paragraph (L) of Batas Pambansa Blg. 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", as Amended, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10243","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10243_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8696-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Three (3) additional Regional Trial Court branches are hereby created in the Eleventh Judicial Region with seats at the City of Davao.\nThe Supreme Court shall assign the branch numbers of the newly-created branches of the Regional Trial Court in the Eleventh Judicial Region."}},{"id":"PH-H8696-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of the three (3) additional branches of the Regional Trial Court to be stationed at the City of Davao, the funding of which shall be included in the annual General Appropriations Act. The funds necessary for the operation of the court(s) herein created shall be appropriated and released only upon the actual organization of the court(s) and the appointment of its personnel."}},{"id":"PH-H8696-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 14(l) of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8696-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p124"};
  FT["PH-H8697"] = {"id":"PH-H8697","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10244_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tacloban市","en":"The Judiciary Reorganization Act of 1980","orig":"An Act Creating Two (2) Additional Branches of the Regional Trial Court in the Province of Leyte to Be Stationed At the City of Tacloban, Amending for the Purpose Section 14, Paragraph (I) of Batas Pambansa Blg. 129, Otherwise Known as \"The Judiciary Reorganization Act of 1980\", as Amended, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 10244","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10244_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8697-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Two (2) additional Regional Trial Court branches are hereby created, in the Eighth Judicial Region with seats at the City of Tacloban, Province of Leyte.\nThe Supreme Court shall assign the branch number of the newly-created branches of the Regional Trial Court in the Eighth Judicial Region."}},{"id":"PH-H8697-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chief Justice of the Supreme Court, in coordination with the Secretary of the Department of Justice, shall immediately include in the Court’s program the operationalization of the two (2) additional branches of the Regional Trial Court in the Province of Leyte to be stationed at the City of Tacloban, the funding of which shall be included in the annual General Appropriations Act. The funds necessary for the operation of the Court(s) herein created shall be appropriated and released only upon the actual organization of the Court(s) and the appointment of its personnel."}},{"id":"PH-H8697-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 14(i) of Batas Pambansa Blg. 129, otherwise known as \"The Judiciary Reorganization Act of 1980″, as amended, and all other laws, rules and regulations which are inconsistent with this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H8697-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its complete publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p124"};
