  FT["PH-H8708"] = {"id":"PH-H8708","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10255_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Lupon市","en":"An Act Establishing a National Agro-Industrial High School in Barangay Bagumbayan, Municipality of Lupon, Province of Davao Oriental to Be Known as Bagumbayan Agro-Industrial High School and Appropriating Funds Therefor","orig":"An Act Establishing a National Agro-Industrial High School in Barangay Bagumbayan, Municipality of Lupon, Province of Davao Oriental to Be Known as Bagumbayan Agro-Industrial High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10255","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10255_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8708-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National Agro-Industrial High School. – There is hereby established, under the supervision of the Department of Education, a national agro-industrial high school in Barangay Bagumbayan, Municipality of Lupon, Province of Davao Oriental to be known as Bagumbayan Agro-Industrial High School."}},{"id":"PH-H8708-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Bagumbayan Agro-Industrial High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8708-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. – The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8708-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p124"};
  FT["PH-H8709"] = {"id":"PH-H8709","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10256_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立San Jose Del Monte市","en":"An Act Establishing a National High School in Barangay Citrus, City of San Jose Del Monte, Province of Bulacan to Be Known as Citrus National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Citrus, City of San Jose Del Monte, Province of Bulacan to Be Known as Citrus National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10256","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10256_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8709-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National High School. – There shall be established, under the supervision of the Department of Education, a national high school in Barangay Citrus, City of San Jose del Monte, Province of Bulacan to be known as Citrus National High School."}},{"id":"PH-H8709-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Citrus National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8709-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. – The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8709-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p124"};
  FT["PH-H8710"] = {"id":"PH-H8710","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10257_2012.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tadian市","en":"An Act Establishing a National High School in Barangay Bunga, Municipality of Tadian, Mountain Province to Be Known as Bunga National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Bunga, Municipality of Tadian, Mountain Province to Be Known as Bunga National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10257","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10257_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8710-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, a national high school in Barangay Bunga, Municipality of Tadian, Mountain Province to be known as Bunga National High School."}},{"id":"PH-H8710-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8710-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department’s program the operationalization of the Bunga National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8710-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p124"};
  FT["PH-H8711"] = {"id":"PH-H8711","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10258_2012.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Bislig City National High School - San Vicente Annex in Barangay San Vicente, City of Bislig, Province of Surigao Del Sur From the Bislig City National High School, Converting It Into An Independent National High School to Be Known as San Vicente National High School and Appropriating Funds Therefor","orig":"An Act Separating the Bislig City National High School - San Vicente Annex in Barangay San Vicente, City of Bislig, Province of Surigao Del Sur From the Bislig City National High School, Converting It Into An Independent National High School to Be Known as San Vicente National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10258","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10258_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8711-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into an Independent National High School. – The Bislig City National High School – San Vicente Annex in Barangay San Vicente, City of Bislig, Province of Surigao del Sur is hereby separated from the Bislig City National High School and converted into an independent national high school to be known as San Vicente National High School."}},{"id":"PH-H8711-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. – All personnel assets, liabilities and records of the Bislig City National High School – San Vicente Annex are hereby transferred to and absorbed by the San Vicente National High School."}},{"id":"PH-H8711-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the San Vicente National High School, the initial funding of which shall be charged against the current year’s appropriation of the Bislig City National High School – San Vicente Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8711-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. – The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8711-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p124"};
  FT["PH-H8712"] = {"id":"PH-H8712","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10259_2012.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Doña Carmen National High School - Tagbina Annex in Barangay Poblacion, Municipality of Tagbina, Province of Surigao Del Sur From the Doña Carmen National High School, Converting It Into An Independent National High School to Be Known as Tagbina National High School and Appropriating Funds Therefor","orig":"An Act Separating the Doña Carmen National High School - Tagbina Annex in Barangay Poblacion, Municipality of Tagbina, Province of Surigao Del Sur From the Doña Carmen National High School, Converting It Into An Independent National High School to Be Known as Tagbina National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10259","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10259_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8712-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into an Independent National High School. – The Doña Carmen National High School – Tagbina Annex in Barangay Poblacion, Municipality of Tagbina, Province of Surigao del Sur is hereby separated from the Doña Carmen National High School and converted into an independent national high school to be known as Tagbina National High School."}},{"id":"PH-H8712-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. – All personnel, assets, liabilities and records of the Doña Carmen National High School – Tagbina Annex are hereby transferred to and absorbed by the Tagbina National High School."}},{"id":"PH-H8712-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Tagbina National High School, the initial funding of which shall be charged against the current year’s appropriation of the Doña Carmen National High School – Tagbina Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8712-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. – The Secretary of Education shall issue rules and regulations that may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8712-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p124"};
