  FT["PH-H8746"] = {"id":"PH-H8746","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2012/ra_10293_2012.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Commonwealth National High School – Kauswagan Annex in Barangay Kauswagan, Municipality of Aurora, Province of Zamboanga Del Sur From the Commonwealth National High School, Converting It Into An Independent National High School to Be Known as Kauswagan National High School and Appropriating Funds Therefor","orig":"An Act Separating the Commonwealth National High School – Kauswagan Annex in Barangay Kauswagan, Municipality of Aurora, Province of Zamboanga Del Sur From the Commonwealth National High School, Converting It Into An Independent National High School to Be Known as Kauswagan National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10293","issuingBody":"Congress of the Philippines","promulgatedDate":"2012-11-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2012/ra_10293_2012.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8746-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Separation and Conversion into a National High School. – The Commonwealth National High School – Kauswagan Annex in Barangay Kauswagan, Municipality of Aurora, Province of Zamboanga del Sur is hereby separated from the Commonwealth National High School and convened into an independent national high school to be known as Kauswagan National High School."}},{"id":"PH-H8746-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Transfer of Assets and Liabilities. – All personnel, assets, liabilities and records of the Commonwealth National High School – Kauswagan Annex are hereby transferred to and absorbed by the Kauswagan National High School."}},{"id":"PH-H8746-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appropriations. – The Secretary of Education shall immediately include in the Department’s program the operationalization of the Kauswagan National High School, the initial funding of which shall be charged against the current year’s appropriations of the Commonwealth National High School – Kauswagan Annex. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H8746-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Implementation. – The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8746-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p124"};
